const fs = require('fs');
const jsdom = require('jsdom');
const { JSDOM } = jsdom;
const html = fs.readFileSync('diamond_web/templates/home.html', 'utf8');

// replace django tags to make valid html
const safeHtml = html.replace(/{%[^%]*%}/g, '').replace(/{{[^}]*}}/g, '""');

const dom = new JSDOM(safeHtml, { runScripts: "dangerously" });
try {
  dom.window.eval(`
    // mock DataTables and Bootstrap
    window.$ = function() {
      return {
        on: function(){ return this; },
        DataTable: function(){ return {}; }
      };
    };
    window.$.fn = { dataTable: { ext: {} } };
    window.bootstrap = { Tooltip: function(){ return { show:()=>{}, hide:()=>{}, setContent:()=>{} }; } };
    window.bootstrap.Tooltip.getInstance = function(){ return null; };
  `);
} catch (e) {
  console.log("Error in mock setup:", e);
}

const scripts = dom.window.document.querySelectorAll('script');
scripts.forEach((s, i) => {
  if (s.textContent) {
    try {
      dom.window.eval(s.textContent);
    } catch(err) {
      console.log('Error in script ' + i, err.message);
      const lines = s.textContent.split('\n');
      console.log(lines[err.lineNumber - 1] || "");
    }
  }
});
